class Solution {
    fun maxStudents(seats:Array<CharArray>):Int{
        val columns=seats[0].size;
        var dp=mutableMapOf(0 to 0);
        for(row in seats){
            var available=0;
            for(c in 0 until columns)if(row[c]=='.')available=available or (1 shl c);
            val next=mutableMapOf<Int,Int>();
            for(mask in 0 until (1 shl columns))if(mask and available.inv()==0&&mask and (mask shl 1)==0)for((previous,value) in dp)if(mask and (previous shl 1)==0&&mask and (previous shr 1)==0)next[mask]=maxOf(next[mask]?:0,value+Integer.bitCount(mask));
            dp=next
        };
        return dp.values.max()
    }
}

